16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "household_size")
67	    private Integer householdSize;
68	
69	    @Column(name = "postcode")
70	    private String postcode;
71	
72	    @Column(name = "bulk_signup_warning")
73	    private Boolean bulkSignupWarning;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    /**
79	     * Fixed city-to-region table used to derive {@link #getLocality() locality}. Any city not
80	     * listed derives the locality {@code 'UNKNOWN'}.
81	     */
82	    private static final Map<String, String> CITY_REGION = Map.of(
83	        "Sydney", "NSW",
84	        "Melbourne", "VIC",
85	        "Brisbane", "QLD");
86	
87	    public String getAddress() {
88	        return this.address;
89	    }
90	
91	    public void setAddress(String address) {
92	        this.address = address;
93	    }
94	
95	    public String getCity() {
96	        return this.city;
97	    }
98	
99	    public void setCity(String city) {
100	        this.city = city;
101	    }
102	
103	    public String getTelephone() {
104	        return this.telephone;
105	    }
106	
107	    public void setTelephone(String telephone) {
108	        this.telephone = telephone;
109	    }
110	
111	    public String getEmail() {
112	        return this.email;
113	    }
114	
115	    public void setEmail(String email) {
116	        this.email = email;
117	    }
118	
119	    public LocalDate getRegistrationDate() {
120	        return this.registrationDate;
121	    }
122	
123	    public void setRegistrationDate(LocalDate registrationDate) {
124	        this.registrationDate = registrationDate;
125	    }
126	
127	    public String getCustomerCode() {
128	        return this.customerCode;
129	    }
130	
131	    public void setCustomerCode(String customerCode) {
132	        this.customerCode = customerCode;
133	    }
134	
135	    /**
136	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
137	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}). Derived
138	     * from the owner's own customer code and registration date; {@code null} when either is absent.
139	     *
140	     * @return the membership number, or {@code null} when it cannot be derived
141	     */
142	    public String getMembershipNumber() {
143	        if (this.customerCode == null || this.registrationDate == null) {
144	            return null;
145	        }
146	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
147	    }
148	
149	    /**
150	     * The owner's numeric membership level, derived from the values frozen at create time. It starts
151	     * at 1, gains 1 when an email address is present, gains 1 when the owner has no namesakes
152	     * ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
153	     *
154	     * @return the membership level, an integer from 1 to 3
155	     */
156	    public Integer getMembershipLevel() {
157	        int level = 1;
158	        boolean hasEmail = this.email != null && !this.email.isBlank();
159	        if (hasEmail) {
160	            level++;
161	        }
162	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
163	        if (hasNoNamesakes) {
164	            level++;
165	        }
166	        return Math.min(level, 3);
167	    }
168	
169	    /**
170	     * The owner's locality, derived from the {@link #getCity() city} using the fixed
171	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). Returns the canonical
172	     * region string, or {@code 'UNKNOWN'} when the city is absent or not in the table.
173	     *
174	     * @return the canonical region string, or {@code 'UNKNOWN'}
175	     */
176	    public String getLocality() {
177	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
178	    }
179	
180	    /**
181	     * The owner's preferred contact channel, derived from the owner's details. Returns
182	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
183	     *
184	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
185	     */
186	    public String getContactPreference() {
187	        boolean hasEmail = this.email != null && !this.email.isBlank();
188	        return hasEmail ? "EMAIL" : "PHONE";
189	    }
190	
191	    /**
192	     * The owner's identity key, the single derived value used for duplicate detection. It is the
193	     * owner's normalized telephone, email (empty when absent) and household id joined with
194	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
195	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
196	     * are equal, so two members of the same household with different telephones differ here and are
197	     * both allowed.
198	     *
199	     * @return the derived identity key
200	     */
201	    public String getIdentityKey() {
202	        return (this.telephone == null ? "" : this.telephone) + "|"
203	            + (this.email == null ? "" : this.email) + "|"
204	            + (this.householdId == null ? "" : this.householdId);
205	    }
206	
207	    public String getHouseholdId() {
208	        return this.householdId;
209	    }
210	
211	    public void setHouseholdId(String householdId) {
212	        this.householdId = householdId;
213	    }
214	
215	    public Integer getNamesakeCount() {
216	        return this.namesakeCount;
217	    }
218	
219	    public void setNamesakeCount(Integer namesakeCount) {
220	        this.namesakeCount = namesakeCount;
221	    }
222	
223	    public Integer getHouseholdSize() {
224	        return this.householdSize;
225	    }
226	
227	    public void setHouseholdSize(Integer householdSize) {
228	        this.householdSize = householdSize;
229	    }
230	
231	    public String getPostcode() {
232	        return this.postcode;
233	    }
234	
235	    public void setPostcode(String postcode) {
236	        this.postcode = postcode;
237	    }
238	
239	    public Boolean getBulkSignupWarning() {
240	        return this.bulkSignupWarning;
241	    }
242	
243	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
244	        this.bulkSignupWarning = bulkSignupWarning;
245	    }
246	
247	    /**
248	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
249	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
250	     */
251	    @PrePersist
252	    void onCreate() {
253	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
254	    }
255	
256	    /**
257	     * Resolves the effective registration date and rolls it onto a business day. An absent
258	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
259	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
260	     * becomes the following Monday, while any weekday is returned unchanged.
261	     *
262	     * <p>This is the single definition of both the defaulting and the business-day roll, used
263	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
264	     * stamps the owner and by the create endpoint that counts owners per business day.
265	     *
266	     * @param supplied the registration date from the request, or {@code null} when none was supplied
267	     * @return the effective registration date, guaranteed to fall on a business day
268	     */
269	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
270	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
271	        return switch (effective.getDayOfWeek()) {
272	            case SATURDAY -> effective.plusDays(2);
273	            case SUNDAY -> effective.plusDays(1);
274	            default -> effective;
275	        };
276	    }
277	
278	    protected Set<Pet> getPetsInternal() {
279	        if (this.pets == null) {
280	            this.pets = new HashSet<>();
281	        }
282	        return this.pets;
283	    }
284	
285	    protected void setPetsInternal(Set<Pet> pets) {
286	        this.pets = pets;
287	    }
288	
289	    public List<Pet> getPets() {
290	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
291	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
292	        return Collections.unmodifiableList(sortedPets);
293	    }
294	
295	    public void setPets(List<Pet> pets) {
296	        this.pets = new HashSet<>(pets);
297	    }
298	
299	    public void addPet(Pet pet) {
300	        getPetsInternal().add(pet);
301	        pet.setOwner(this);
302	    }
303	
304	    /**
305	     * Return the Pet with the given name, or null if none found for this Owner.
306	     *
307	     * @param name to test
308	     * @return true if pet name is already in use
309	     */
310	    public Pet getPet(String name) {
311	        return getPet(name, false);
312	    }
313	
314	    /**
315	     * Return the Pet with the given name, or null if none found for this Owner.
316	     *
317	     * @param name to test
318	     * @return true if pet name is already in use
319	     */
320	    public Pet getPet(String name, boolean ignoreNew) {
321	        name = name.toLowerCase();
322	        for (Pet pet : getPetsInternal()) {
323	            if (!ignoreNew || !pet.isNew()) {
324	                String compName = pet.getName();
325	                compName = compName.toLowerCase();
326	                if (compName.equals(name)) {
327	                    return pet;
328	                }
329	            }
330	        }
331	        return null;
332	    }
333	
334	    public Pet getPet(Integer petId) {
335	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
336	    }
337	
338	    @Override
339	    public String toString() {
340	        return new ToStringCreator(this)
341	
342	            .append("id", this.getId())
343	            .append("new", this.isNew())
344	            .append("lastName", this.getLastName())
345	            .append("firstName", this.getFirstName())
346	            .append("address", this.address)
347	            .append("city", this.city)
348	            .append("telephone", this.telephone)
349	            .toString();
350	    }
351	}
